	PREPARE stmt1 FROM @sql;
	EXECUTE stmt1;
    
	INSERT INTO Temp_RootCTSCustIDs(CTSCustId, SubscriberID)
    SELECT DISTINCT c.CTSCustID, c.SubscriberID
    FROM Temp_Username AS u
		INNER JOIN CTS_DataCenter.CTSCustomer AS c on u.Username = c.UserName;
    
    INSERT INTO Temp_AffectedDevices(CTSCustID, DCSDeviceID)
    SELECT DISTINCT t.CTSCustID, a.DCSDeviceID
    FROM CTS_DataCenter.AssociationByDevice AS a    
		INNER JOIN Temp_RootCTSCustIDs AS t ON a.CTSCustID = t.CTSCustID;

    INSERT INTO Temp_AssociationException(FromCTSCustID, ToCTSCustID)
    SELECT DISTINCT t.CTSCustID
		,	CASE WHEN e.LeastCTSCustID_Order = t.CTSCustID THEN e.GreatestCTSCustID_Order ELSE e.LeastCTSCustID_Order END
    FROM CTS_DataCenter.CustException AS e
		INNER JOIN Temp_RootCTSCustIDs AS t ON e.LeastCTSCustID_Order = t.CTSCustID OR e.GreatestCTSCustID_Order = t.CTSCustID;
    
    INSERT IGNORE INTO CTS_DataCenter.SpecialCustomerClass(CTSCustID, CustID, RootCTSCustID, SubscriberID, CustomerClass, CreatedBy, CreatedDate)
	SELECT DISTINCT a.CTSCustID, 0, t.CTSCustID, t.SubscriberID, lv_CustomerClass, lv_CreatedBy, lv_CurrentDateTime
    FROM Temp_RootCTSCustIDs AS t
		INNER JOIN Temp_AffectedDevices AS d ON t.CTSCustID = d.CTSCustID
		INNER JOIN CTS_DataCenter.AssociationByDevice AS a ON a.DCSDeviceID = d.DCSDeviceID AND a.SubscriberID = t.SubscriberID
        LEFT JOIN Temp_AssociationException AS e ON t.CTSCustID = e.FromCTSCustID AND a.CTSCustID = e.ToCTSCustID
	WHERE a.CTSCustID <> d.CTSCustID AND (e.FromCTSCustID IS NULL OR e.ToCTSCustID IS NULL);    
    
    SET SQL_SAFE_UPDATES = 0;
    UPDATE CTS_DataCenter.SpecialCustomerClass AS s
		INNER JOIN CTS_DataCenter.CTSCustomer AS c ON s.CTSCustID = c.CTSCustID
	SET s.CustID = c.CustID
    WHERE s.CustID = 0;  

